class FileSystem {Set<String>dirs=new HashSet<>(Arrays.asList("/"));Map<String,String>files=new HashMap<>();public FileSystem(){}public List<String>ls(String path){if(files.containsKey(path))return Arrays.asList(path.substring(path.lastIndexOf('/')+1));String prefix=path.equals("/")?"/":path+"/";TreeSet<String>out=new TreeSet<>();Set<String>all=new HashSet<>(dirs);all.addAll(files.keySet());for(String p:all)if(p.startsWith(prefix)&&!p.equals(path)){String name=p.substring(prefix.length());if(!name.contains("/"))out.add(name);}return new ArrayList<>(out);}public void mkdir(String path){String current="";for(String p:path.substring(1).split("/")){current+="/"+p;dirs.add(current);}}public void addContentToFile(String filePath,String content){files.merge(filePath,content,String::concat);}public String readContentFromFile(String filePath){return files.get(filePath);}}
